#!/usr/bin/env bash
# GAP-029 FINAL verification on the restore host (streamanator, user arm). DERIVED from the reviewed tools/v2/gap029-ops/restore-assemble-host.sh: steps A0-A3
# (inputs re-verified by the independent `check-capture`/`check-target`, guarded cluster start with an exclusive-listener proof, restore into a guarded
# disposable database, restore evidence generated by the assembler from the restored database) are the same commands; A4 (stage assembly) is replaced by
# V1-V4 below, because no stage is being prepared. Nothing here touches production, the DEV database or any DEV service; every check is read-only.
#
#   V0 bind the evidence: revision, tool and POLICY file hashes (corpus, adjudications, deferrals, Lyons/Webster/rookie decisions), DEV baseline
#   V1 targeted read-only checks of the four stages' data (final-verify-sql.mjs), incl. differential against the retained post-S2 / post-S3 restores
#   V2 the S4 digests and the S2 gate VERIFY via the stage tools' own read helpers (final-verify-py.py)
#   V3 the production-scope Gridley corpus on this restore (diagnostic mode; its test file exits 1 by design while strict parity retains 118 findings)
#   V4 corpus acceptance: the reviewed corpus-summary.mjs + final-corpus-checks.mjs
#
# Usage (as arm): W=<workspace> R=<40-hex revision> CAPDIR=<copied capture dir> PROD_TARGET=<production target json> TAG=<[a-z0-9_]+> EXPECT=<dir with s1..s4-plan.json>
#   FV=<directory OUTSIDE the checkout holding final-verify-sql.mjs, final-verify-py.py, final-corpus-checks.mjs> CHILD=<S2 child.json on this host> PRIOR_S3_DB=<post-S2 restore db> PRIOR_S4_DB=<post-S3 restore db> [PORT=55493] bash final-restore-verify-host.sh
set -u -o pipefail
: "${FV:?}" "${W:?}" "${R:?}" "${CAPDIR:?}" "${PROD_TARGET:?}" "${TAG:?}" "${EXPECT:?}" "${CHILD:?}" "${PRIOR_S3_DB:?}" "${PRIOR_S4_DB:?}"
[[ "$TAG" =~ ^[a-z0-9_]+$ ]] || { echo "STOP TAG must match [a-z0-9_]+"; exit 2; }
export PATH="$HOME/.nvm/versions/node/v22.23.2/bin:$PATH"
export PYTHONDONTWRITEBYTECODE=1
CAND="$W/cand"; HERE="$CAND/tools/v2/gap029-ops"; HARD="$CAND/docs/v2/evidence/gap029-hardening-20261103/scripts"
PROFILE="$HERE/profile.production.env"
[ -r "$PROFILE" ] || { echo "STOP profile unreadable"; exit 2; }
if grep -qvE '^(#.*|[A-Z_]+="[^"$`\\]*"|)$' "$PROFILE"; then echo "STOP profile contains a line that is not KEY=\"plain value\""; exit 2; fi
# shellcheck disable=SC1090
. "$PROFILE"
PORT=${PORT:-55493}; EVP="$W/evidence-private/$TAG"
export AFLDB_PYTHON="${PY:-$W/venv/bin/python}"
mkdir -p -m 700 "$W/evidence-private"; [ -e "$EVP" ] && { echo "STOP $EVP exists; choose a new TAG (evidence is never overwritten)"; exit 2; }; mkdir -m 700 "$EVP"
export AFLDB_V2_PG_ROOT="$W/pg-root" AFLDB_V2_PG_BIN=/usr/lib/postgresql/16/bin AFLDB_V2_PG_PORT=$PORT
SUM="$EVP/final-summary.txt"; : > "$SUM"
say() { echo "$(date -u +%FT%TZ) $*" | tee -a "$SUM"; }
rec() { echo "$*" | tee -a "$SUM"; }
IR() { (cd "$CAND" && node --import tsx tools/v2/isolated-pg.ts "$@"); }
RUNDB() { local db="$1"; shift; (cd "$CAND" && node --import tsx tools/v2/isolated-pg.ts run "$db" -- "$@"); }
RDB=afldb_v2_gap029_${TAG}_rst_test
dev_services() { for u in afldb.service postgresql@16-main.service; do echo "$u $(systemctl is-active $u 2>&1) MainPID=$(systemctl show -p MainPID --value $u 2>&1)"; done; }
FAILS=0; ok() { rec "PASS $1"; }; bad() { FAILS=$((FAILS+1)); rec "FAIL $1"; }

say "A0 inputs (profile $PROFILE_NAME, evidence class $EVIDENCE_CLASS)"
[ "$(cd "$CAND" && git rev-parse HEAD)" = "$R" ] && [ "$(cd "$CAND" && git status --porcelain | wc -l)" = 0 ] && ok "candidate clean at $R" || { bad "candidate not clean at $R"; exit 3; }
case "$CAPDIR$PROD_TARGET$W" in *"$CAND"*) echo "STOP inputs must be outside the checkout"; exit 3 ;; esac
(cd "$CAND" && node --import tsx tools/v2/gap029-ops.ts check-capture --stage S4 --dir "$CAPDIR" --profile "$PROFILE") | tee "$EVP/check-capture.txt" || { bad "capture directory failed its independent check"; exit 3; }
(cd "$CAND" && node --import tsx tools/v2/gap029-ops.ts check-target --target "$PROD_TARGET" --profile "$PROFILE" --dir "$CAPDIR") | tee -a "$SUM" || { bad "production target file failed its check"; exit 3; }
DUMP=$(ls "$CAPDIR"/afldb_prod-*.dump); PROVENANCE=$(ls "$CAPDIR"/afldb_prod-*.provenance.json)
DUMP_SHA=$(sha256sum "$DUMP" | cut -d' ' -f1)
ss -ltn 2>/dev/null | awk '{print $4}' | grep -E ":$PORT$" && { bad "port $PORT already listening"; exit 3; }
rec "dump sha256 $DUMP_SHA verified by check-capture; stage-4-accepted production backup taken after S4 (final verification)"
dev_services | tee "$EVP/dev-before.txt" >> "$SUM"

fin() { local rc=$?; say "V9 stop the cluster and prove isolation"; IR stop || true; sleep 2
  ss -ltn | awk '{print $4}' | grep -E ":$PORT$" && bad "port still listening"
  dev_services > "$EVP/dev-after.txt"; cmp -s "$EVP/dev-before.txt" "$EVP/dev-after.txt" && ok "DEV services unchanged (afldb.service, postgresql@16-main.service: state and MainPID)" || bad "DEV service state differs"
  [ "$(cd "$CAND" && git status --porcelain | wc -l)" = 0 ] && ok "pinned checkout still clean at $R" || bad "pinned checkout is not clean"
  rec "FINAL VERIFICATION RESULT: $([ "$FAILS" = 0 ] && echo PASS || echo "FAIL ($FAILS)")  revision $R  restored database $RDB  host $(hostname) user $(whoami)"; exit $([ "$FAILS" = 0 ] && echo 0 || echo 1); }
trap fin EXIT
say "A1 start the guarded cluster"
( IR start > "$EVP/pg-start.out" 2>&1 < /dev/null & ); sleep 4
IR status || exit 4
pmpid=$(head -1 "$AFLDB_V2_PG_ROOT/data/postmaster.pid"); ss -ltnp 2>/dev/null | grep ":$PORT " > "$EVP/listener.txt"
grep -q "127.0.0.1:$PORT" "$EVP/listener.txt" && grep -q "pid=$pmpid," "$EVP/listener.txt" && [ "$(grep -c . "$EVP/listener.txt")" = 1 ] && ok "listener is exclusively the cluster we started (127.0.0.1:$PORT)" || { bad "listener not exclusive"; exit 4; }

say "A2 restore into a guarded disposable database"
IR create-db "$RDB" || exit 5
RESTORED_AT_START=$(date -u +%FT%T.%3NZ)
RUNDB "$RDB" node "$HERE/restore.mjs" "$DUMP" "$DUMP_SHA" | tee "$EVP/restore.out" || { bad "restore"; exit 5; }
RESTORED_AT=$(date -u +%FT%T.%3NZ)
rec "restore_started=$RESTORED_AT_START restored_at=$RESTORED_AT"
cp "$HERE/probe-dbs.mjs" "$CAND/.probe-dbs.mjs"; RUNDB "$RDB" node .probe-dbs.mjs "$RDB" | tee "$EVP/restore-probe.txt"; rm -f "$CAND/.probe-dbs.mjs"
LEDGER_PREFIX=${LEDGER_PREFIX:-${EXPECT_LEDGER_LAST%%_*}_}
grep -qF '"ledger":"'"$LEDGER_PREFIX" "$EVP/restore-probe.txt" && ok "restored ledger starts $LEDGER_PREFIX" || { bad "restored ledger does not start $LEDGER_PREFIX"; exit 5; }
TOC=$(/usr/lib/postgresql/16/bin/pg_restore --list "$DUMP" | grep -cv '^;'); rec "archive toc entries: $TOC"

say "A3 restore evidence (identity proven by query inside the guarded database; source identity from the capture provenance, checked against the production target)"
RUNDB "$RDB" bash -c "cd '$CAND' && node --import tsx tools/v2/gap029-assemble-restore-evidence.ts restore-evidence --provenance '$PROVENANCE' --dump '$DUMP' --dump-sha256 '$DUMP_SHA' --restored-at '$RESTORED_AT' --toc-entries '$TOC' --production-target '$PROD_TARGET' --out '$EVP/restore-evidence.json'" && ok "restore evidence generated from the guarded restored database" || { bad "restore evidence"; exit 6; }
rec "restore-evidence.json sha256 $(sha256sum "$EVP/restore-evidence.json" | cut -d' ' -f1)"
rec "production target sha256 $(sha256sum "$PROD_TARGET" | cut -d' ' -f1)"; cp "$PROD_TARGET" "$EVP/production-target.json"

say "V0 bind the evidence: revision, tool and policy file hashes"
{ echo "revision $R"; echo "head $(cd "$CAND" && git rev-parse HEAD)";
  for f in tools/v2/gap029-captaincy-additions-production.ts tools/v2/gap029-rookie-selections-production.ts tools/v2/gap029-draft-link-production.py tools/v2/gap029-sibling-pair-production.py tools/v2/gap029-common.ts tools/v2/gap029_common.py tools/v2/gap029-assemble-restore-evidence.ts tools/migration/family_siblings.py tools/rebuild/draftguru/import_draftguru.py tools/rebuild/draftguru/bridge_import_gate.py data/players/sibling-relationships.csv \
           tests/integration/gridley-corpus.test.ts tests/gridley-release-policy.ts tests/gridley-known-answer-adjudications.ts tests/rookie-relisting-outcomes.ts tests/fixtures/gridley/corpus.json \
           data/reference/gridley-approved-deferrals.json data/reference/gridley-approved-sibling-disagreements.json data/reference/gridley-sibling-eligibility-webster.json data/players/gridley-known-answer-adjudications.csv data/players/rookie-relisting-outcomes.csv; do
    [ -f "$CAND/$f" ] && echo "$(tr -d '\r' < "$CAND/$f" | sha256sum | cut -d' ' -f1)  $f  (git blob $(cd "$CAND" && git rev-parse "HEAD:$f"))" || echo "MISSING $f"; done; } | tee "$EVP/binding.txt" >> "$SUM"
grep -q '^MISSING' "$EVP/binding.txt" && bad "a bound file is missing" || ok "tool and policy files bound to revision $R (LF-normalised sha256 + git blob ids)"
for d in "$PRIOR_S3_DB" "$PRIOR_S4_DB"; do RUNDB "$RDB" node -e "
const postgres=require('postgres');const u=new URL(process.env.AFLDB_TEST_DATABASE_URL);u.pathname='/$d';const s=postgres(u.toString(),{max:1,connect_timeout:5,onnotice:()=>{}});
s\`SELECT current_database() AS db, (SELECT max(name) FROM afldb_meta.schema_migrations) AS ledger\`.then(r=>{console.log(JSON.stringify(r[0]));return s.end()}).catch(e=>{console.log('ERR '+e.message);process.exit(1)})" ; done | tee "$EVP/prior-dbs.txt"
grep -q ERR "$EVP/prior-dbs.txt" && { bad "a retained comparison restore is missing"; exit 7; } || ok "retained post-S2 and post-S3 comparison restores present"

say "V1 targeted read-only checks of the four stages' data"
cp "$FV/final-verify-sql.mjs" "$CAND/.final-verify-sql.mjs"
RUNDB "$RDB" bash -c "cd '$CAND' && node .final-verify-sql.mjs '$RDB' '$EXPECT' '$PRIOR_S4_DB' '$PRIOR_S3_DB'" > "$EVP/verify-sql.out" 2>&1; rc=$?; rm -f "$CAND/.final-verify-sql.mjs"
cat "$EVP/verify-sql.out" >> "$SUM"; cat "$EVP/verify-sql.out"; [ $rc = 0 ] && ok "V1 SQL verification" || bad "V1 SQL verification (exit $rc)"

say "V2 S4 digests and the S2 gate VERIFY via the stage tools' own read helpers"
RUNDB "$RDB" env CAND="$CAND" EXPECT="$EXPECT" RDB="$RDB" CHILD="$CHILD" "$AFLDB_PYTHON" -B "$FV/final-verify-py.py" > "$EVP/verify-py.out" 2>&1; rc=$?
cat "$EVP/verify-py.out" >> "$SUM"; cat "$EVP/verify-py.out"; [ $rc = 0 ] && ok "V2 Python verification" || bad "V2 Python verification (exit $rc)"

say "V3 production-scope Gridley corpus on this restore (diagnostic mode)"
mkdir -p "$EVP/corpus"
RUNDB "$RDB" bash -c "cd '$CAND' && AFLDB_GRIDLEY_DIAGNOSTIC=1 AFLDB_GRIDLEY_REPORT='$EVP/corpus/report.json' node node_modules/vitest/vitest.mjs run tests/integration/gridley-corpus.test.ts" > "$EVP/corpus/run.log" 2>&1; crc=$?
rec "corpus test file exit $crc (diagnostic mode exits 1 by design while strict parity retains its 118 accepted findings; the failing assertions are listed below)"
sed 's/\x1b\[[0-9;]*m//g' "$EVP/corpus/run.log" | grep -E "✓|×|FAIL|Tests |Test Files|AssertionError" | head -40 | tee -a "$SUM"
[ -s "$EVP/corpus/report.json" ] && rec "corpus report sha256 $(sha256sum "$EVP/corpus/report.json" | cut -d' ' -f1)" || bad "corpus produced no report"

say "V4 corpus acceptance"
node "$HARD/corpus-summary.mjs" "$EVP/corpus/report.json" > "$EVP/corpus/summary.json" 2>&1 && ok "reviewed corpus summary: conformance PASS, 0 unapproved, 0 incorrect known answers, strict parity retained at 118" || { bad "reviewed corpus summary"; head -50 "$EVP/corpus/summary.json"; }
node "$FV/final-corpus-checks.mjs" "$EVP/corpus/report.json" > "$EVP/corpus/extra-checks.json" 2>&1 && ok "extra corpus checks: 78 deferrals + 40 disagreements, adjudications current, production-scope counts" || { bad "extra corpus checks"; head -80 "$EVP/corpus/extra-checks.json"; }
cat "$EVP/corpus/extra-checks.json" | tail -40 >> "$SUM"
